/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('.').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'
 print('\\nFILE',f.name[:-4])
 for i,l in enumerate(lines):
  m=re.match(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'governing law|governed by|governed and|laws of|law of|Israel',l,re.I):
   if re.search(r'govern|Israel',l,re.I):
    print('PAGE',page, ' | '.join(lines[max(0,i-1):i+3]))
PY"

